let glowModelCache: any = null;
export function getGlowModel() {
  if (glowModelCache) return glowModelCache;
  const H = LIGHT_HEADER as any;
  const raw = atob(LIGHT_DATA.replace(/_/g, "+").replace(/\$/g, "/"));
  const view = new DataView(new ArrayBuffer(raw.length));
  for (let i = 0; i < raw.length; i++) view.setUint8(i, raw.charCodeAt(i));
  let at = 0;
  const block = (name: string) => {
    const { shape, scale } = H[name];
    const row = shape.slice(1).reduce((a: number, b: number) => a * b, 1);
    const out = new Float32Array(shape[0] * row);
    for (let r = 0; r < shape[0]; r++) {
      for (let j = 0; j < row; j++) { out[r * row + j] = view.getInt16(at, true) * scale[r]; at += 2; }
    }
    return out;
  };
  const model = {
    D1: H.D + 1, KB: H.K, KR: H.KR, P: H.P, HARMONICS: H.H, NB: 2 * H.H + 1, domain: H.domain,
    bodyModes: block("bodyModes"),
    bodyWeights: block("bodyWeights"),
    rimModes: block("rimModes"),
    rimWeights: block("rimWeights"),
    bytes: raw.length, read: at
  };
  glowModelCache = model;
  return model;
}
